(function(root){'use strict';if(root.RC4BankData)return;
let config,manifest,base,core,bundle,engine,bodyIndex;const loadedGroups=new Set(),loadedTextFiles=new Set(),loadedMeta={value:false};let functions=null,querySerial=0,lastQuery=null,latestRetry=null;
const intents={};const state={ready:false,version:null,query:null,history:[],loadedGroups:0,loadedTextFiles:0};
const byId=new Map(),questions=new Map(),tasks=new Map(),text={gt:{},qt:{}};
const resolve=file=>new URL(file,base).href;
function panel(){let box=document.getElementById('bank-data-status');if(!box){box=document.createElement('div');box.id='bank-data-status';box.className='callout';box.setAttribute('aria-live','polite');box.hidden=true;document.body.insertBefore(box,document.getElementById('app'));}return box;}
function message(label,error=null,retry=null){const box=panel();box.hidden=false;box.replaceChildren();const p=document.createElement('p');p.setAttribute('role',error?'alert':'status');p.textContent=label;box.append(p);if(error){const detail=document.createElement('small');detail.textContent='资源：'+decodeURI(error.url||'未知')+'；阶段：'+(error.stage||'加载')+'；尝试：'+(error.attempt||1)+'/3；类型：'+error.name;box.append(detail);const button=document.createElement('button');button.textContent='重试缺失资源';button.onclick=()=>{const run=retry||latestRetry;if(run)run();};box.append(button);}}
function failure(err,retry){latestRetry=retry||latestRetry;message('题库资源未完成，保留上一次有效结果。'+err.message,err,latestRetry);}
function progress(event){state.history.push(event);if(state.history.length>1000)state.history.shift();if(event.stage==='failure')return;const stages={download:'正在下载题库数据',verify:'正在校验题库数据','script-download':'正在加载题库程序',cache:'正在读取已验证缓存'};if(stages[event.stage]){const percentage=event.total?Math.min(100,Math.round((event.loaded||0)/event.total*100)):null;message(stages[event.stage]+(percentage===null?'':' '+percentage+'%')+'：'+decodeURI(event.url).split('/').pop());}}
async function file(name){return RC4BankResources.json(resolve(name),manifest.files[name],manifest.version);}
function applyText(value){Object.assign(text.gt,value.gt);Object.assign(text.qt,value.qt);}
async function ensureTextFile(name){if(loadedTextFiles.has(name))return;const value=await file(name);applyText(value);loadedTextFiles.add(name);state.loadedTextFiles=loadedTextFiles.size;}
async function limited(items,fn){let next=0;await Promise.all(Array.from({length:Math.min(3,items.length)},async()=>{for(;;){const i=next++;if(i>=items.length)return;await fn(items[i]);}}));}
function attach(model){Object.assign(model.gt,text.gt);Object.assign(model.qt,text.qt);if(!engine)engine=model;return model;}
async function ensureSearch(model,filters,records){
 if(!filters.query?.trim())return;
 const candidates=functions.Ug(model,{...filters,query:''},records).groups.map(g=>g.id),normalized=functions.la(filters.query);
 // 精确ID可使原引擎加入不在一般searchRows中的父问，必须补入其范围。
 for(const q of Object.values(model.qm))if(functions.la(q.id)===normalized)candidates.push(q.groupId,model.qm[q.master]?.groupId);
 for(const task of Object.values(model.taskById))if(functions.la(task.id)===normalized)candidates.push(task.groupId,model.qm[task.originalQuestionId]?.groupId);
 for(const g of model.bank.groups)if(functions.la(g.id)===normalized)candidates.push(g.id,g.master);
 const names=[...new Set(candidates.filter(Boolean).map(id=>manifest.textGroups[id]))];if(names.some(x=>!x))throw Error('必要检索范围缺少稳定资源映射');
 await limited(names,ensureTextFile);if(names.some(name=>!loadedTextFiles.has(name)))throw Error('必要检索范围尚未完整，禁止提交零命中');
}
function query(model,filters,records,run){const sequence=++querySerial;state.query={sequence,filters:{...filters},phase:'loading'};return ensureSearch(model,filters,records).then(()=>{Object.assign(model.gt,text.gt);Object.assign(model.qt,text.qt);const result=run(model,filters,records);if(sequence===querySerial){state.query={sequence,filters:{...filters},phase:'ready',groups:result.groups.length,questions:result.questionCount};lastQuery=result;panel().hidden=true;}return result;});}
function applyGroup(data){Object.assign(byId.get(data.id),data.group);for(const [id,value]of Object.entries(data.questions))Object.assign(questions.get(id),value);for(const task of data.tasks){const target=tasks.get(task.data.id);if(target)Object.assign(target,task.data);}}
async function ensureGroups(ids){await limited([...new Set(ids)].filter(id=>byId.has(id)&&!loadedGroups.has(id)),async id=>{const value=await file(manifest.groups[id].file);if(value.id!==id)throw Error('题组资源ID不匹配');applyGroup(value);await root.RC4BankLoader.content(manifest.groups[id].contentRef);loadedGroups.add(id);state.loadedGroups=loadedGroups.size;});panel().hidden=true;}
async function ensureQuestions(ids){await ensureGroups(ids.map(id=>questions.get(id)?.groupId).filter(Boolean));}
async function ensureAll(){await ensureGroups([...byId.keys()]);if(!loadedMeta.value){const value=await file(manifest.extras);for(const key of ['modernTypeRelease','modernIncrementalRelease','poetryTypeRelease'])for(const task of value.catalog[key]?.searchIndex||[])if(tasks.has(task.id))Object.assign(tasks.get(task.id),task);Object.assign(bundle.catalog,value.catalog);loadedMeta.value=true;}await limited([...new Set(Object.values(manifest.textGroups))],ensureTextFile);panel().hidden=true;}
async function init(settings){config=settings;base=new URL(settings.base,document.baseURI);RC4BankResources.observe(progress);manifest=await RC4BankResources.json(resolve('manifest.json'),settings.manifest,settings.version);if(manifest.schema!=='rc4-bank-layered-1'||manifest.sourceCommit!==settings.sourceCommit)throw Error('题库版本协议不匹配');state.version=manifest.version;const data=await file(manifest.core);core=data;bundle=root.RC4_BANK={catalog:data.catalog,report:data.report,content:{},media:{},wordFormat:''};for(const group of bundle.catalog.groups)byId.set(group.id,group);for(const question of bundle.catalog.questions)questions.set(question.id,question);for(const key of ['modernTypeRelease','modernIncrementalRelease','poetryTypeRelease'])for(const task of bundle.catalog[key]?.searchIndex||[])tasks.set(task.id,task);if(byId.size!==694||questions.size!==3086)throw Error('题库规模验证失败');return bundle;}
async function start(api){functions=api;engine=api.Qu(bundle.catalog);const parsed=api.parse(location.hash,api.defaults),filters=api.clean(engine,parsed.filters);let records=[];try{const raw=JSON.parse(localStorage.getItem('chinese-bank-html-records-v1:'+bundle.catalog.bankId)||'[]');if(Array.isArray(raw))records=raw;}catch{}
 await ensureSearch(engine,filters,[]);if(records.length)await ensureSearch(engine,filters,records);const ids=[];if(parsed.group)ids.push(parsed.group);try{for(const id of JSON.parse(localStorage.getItem('chinese-bank-html-basket-v2:'+bundle.catalog.bankId)||'[]')){const q=questions.get(id);if(q)ids.push(q.groupId);}}catch{}
 Object.assign(engine.gt,text.gt);Object.assign(engine.qt,text.qt);await ensureGroups(ids);if(['manage','overview'].includes(parsed.view))await ensureAll();return bundle;
}
function markReady(){state.ready=true;panel().hidden=true;document.body.dataset.bankReady='true';}
function initLoader(){const prefix=new URL('../../',base);const asset=name=>{const x=manifest.assets[name];return {...x,url:new URL(x.path,base).href};};
 const mediaInfo=value=>{const index=root.RC4_MEDIA_INDEX;if(!index)return null;if(index[value])return index[value];try{const url=new URL(value,document.baseURI);url.search='';url.hash='';return Object.values(index).find(x=>x.url===url.href)||null;}catch{return null;}};
 root.RC4BankLoader={content:async id=>{if(!/^[a-zA-Z0-9_-]+$/.test(id))throw Error('无效正文标识');if(!bodyIndex)bodyIndex=(await file(manifest.bodyIndex)).bodies;const meta=bodyIndex[id];if(!meta)throw Error('正文ID不在发布版本清单');await RC4BankResources.script(new URL('正文/'+id+'.js',prefix).href,meta,()=>!!bundle.content[id]?.question,{kind:'content'});},word:async()=>{const a=asset('word');await RC4BankResources.script(a.url,a,()=>!!bundle.wordFormat,{kind:'word',timeout:420000});return bundle.wordFormat;},mediaInfo,isMediaURL:v=>!!mediaInfo(v),fetchMedia:v=>{const data=mediaInfo(v);if(!data)throw Error('无效题图资源');return fetch(data.url);},decorateImage:image=>{const data=mediaInfo(image.getAttribute('src')||'');if(!data)return;if(!image.hasAttribute('width'))image.width=data.width;if(!image.hasAttribute('height'))image.height=data.height;image.dataset.rc4Image='true';}};
 return asset;
}
root.RC4BankData={init,start,attach,query,ensureGroups,ensureQuestions,ensureAll,initLoader,markReady,failure,offerRetry:fn=>{latestRetry=fn;},sourceView:(id,short)=>core.sources[id]?.[short?'short':'full']||null,nextIntent:key=>intents[key]=(intents[key]||0)+1,isCurrent:(key,n)=>intents[key]===n,cancelIntent:key=>intents[key]=(intents[key]||0)+1,state:()=>({...state,loadedGroups:[...loadedGroups],loadedTextFiles:[...loadedTextFiles],resources:RC4BankResources.state()}),lastResult:()=>lastQuery,engine:()=>engine,api:()=>functions};
})(window);
